     1	export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
     2	export type QuoteStep = { op: 'quote'; items: Item[] };
     3	export type Damage = { itemType: string; amount: number };
     4	export type ClaimStep = { op: 'claim'; policy: number; incident: { cause: string; damages: Damage[] } };
     5	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: (QuoteStep | ClaimStep)[] };
     6	export type Result = { premium: number } | { payout: number; remainingCap: number };
     7	
     8	const PROCESSING_FEE = 5;
     9	// Percentages are whole numbers; amounts multiplied by a percentage are kept in
    10	// hundredths of a G so intermediate values stay exact until the final rounding.
    11	const FIRST_INSURANCE_SURCHARGE_PCT = 10;
    12	const LOYALTY_DISCOUNT_PCT = 20;
    13	const LOYALTY_MIN_YEARS = 2;
    14	const FOLLOW_UP_DISCOUNT_PCT = 15;
    15	const CURSE_SURCHARGE_PCT = 50;
    16	const HIGH_ENCHANTMENT_SURCHARGE_PCT = 30;
    17	const HIGH_ENCHANTMENT_PREMIUM_THRESHOLD = 5;
    18	
    19	function itemSurchargePct(item: Item): number {
    20	  let pct = 0;
    21	  if (item.cursed) pct += CURSE_SURCHARGE_PCT;
    22	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_PREMIUM_THRESHOLD) pct += HIGH_ENCHANTMENT_SURCHARGE_PCT;
    23	  return pct;
    24	}
    25	
    26	const BASE_PREMIUMS: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };
    27	const COMPONENT_TYPES = new Set(['rune', 'moonstone']);
    28	const BLOCK_SIZE = 3;
    29	const BLOCK_BASE_PREMIUM = 60;
    30	
    31	function policyBasePremium(items: Item[]): number {
    32	  const componentCounts = new Map<string, number>();
    33	  let base = 0;
    34	  for (const item of items) {
    35	    if (COMPONENT_TYPES.has(item.type)) {
    36	      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
    37	    } else {
    38	      base += BASE_PREMIUMS[item.type];
    39	    }
    40	  }
    41	  for (const [type, count] of componentCounts) {
    42	    base += count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
    43	  }
    44	  return base;
    45	}
    46	
    47	function quotePremium(items: Item[], yearsWithMHPCO: number, isFollowUp: boolean): number {
    48	  const base = policyBasePremium(items);
    49	  const itemSurcharges = items.reduce(
    50	    (sum, item) => sum + BASE_PREMIUMS[item.type] * itemSurchargePct(item),
    51	    0,
    52	  );
    53	  let policyPct = 100 + FIRST_INSURANCE_SURCHARGE_PCT;
    54	  if (yearsWithMHPCO >= LOYALTY_MIN_YEARS) policyPct -= LOYALTY_DISCOUNT_PCT;
    55	  if (isFollowUp) policyPct -= FOLLOW_UP_DISCOUNT_PCT;
    56	  const hundredths = base * policyPct + itemSurcharges;
    57	  return Math.ceil(hundredths / 100) + PROCESSING_FEE;
    58	}
    59	
    60	const INSURANCE_VALUES: Record<string, number> = { sword: 1000, amulet: 600, staff: 800, potion: 400, rune: 250, moonstone: 250 };
    61	const DEDUCTIBLE = 100;
    62	const CAP_MULTIPLIER = 2;
    63	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
    64	// Integer damages halved are exact in floating point, so no scaling is needed here.
    65	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
    66	
    67	function reimbursable(item: Item, amount: number): number {
    68	  // The 50 % clause wins over dragon material's full reimbursement.
    69	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD) return amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
    70	  return amount;
    71	}
    72	
    73	type Policy = { items: Item[]; remainingCap: number };
    74	
    75	function createPolicy(items: Item[]): Policy {
    76	  const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
    77	  return { items, remainingCap: insuranceSum * CAP_MULTIPLIER };
    78	}
    79	
    80	function processClaim(policy: Policy, damages: Damage[]): { payout: number; remainingCap: number } {
    81	  const unclaimed = [...policy.items];
    82	  const desired = damages.reduce((sum, damage) => {
    83	    if (damage.amount < 0) throw new Error(`Invalid damage amount: ${damage.amount}`);
    84	    const index = unclaimed.findIndex((candidate) => candidate.type === damage.itemType);
    85	    if (index === -1) throw new Error(`Damaged item not covered by policy: ${damage.itemType}`);
    86	    const [item] = unclaimed.splice(index, 1);
    87	    return sum + Math.max(0, reimbursable(item, damage.amount) - DEDUCTIBLE);
    88	  }, 0);
    89	  const payout = Math.min(Math.floor(desired), policy.remainingCap);
    90	  policy.remainingCap -= payout;
    91	  return { payout, remainingCap: policy.remainingCap };
    92	}
    93	
    94	export function runScenario(scenario: Scenario): { results: Result[] } {
    95	  let contracts = 0;
    96	  const policies = new Map<number, Policy>();
    97	  return {
    98	    results: scenario.steps.map((step, index): Result => {
    99	      if (step.op === 'claim') {
   100	        return processClaim(policies.get(step.policy)!, step.incident.damages);
   101	      }
   102	      for (const item of step.items) {
   103	        if (!(item.type in BASE_PREMIUMS)) throw new Error(`Unknown item type: ${item.type}`);
   104	      }
   105	      const premium = quotePremium(step.items, scenario.customer.yearsWithMHPCO, contracts > 0);
   106	      contracts++;
   107	      policies.set(index, createPolicy(step.items));
   108	      return { premium };
   109	    }),
   110	  };
   111	}
